package com.lianxibu.site.domain.jobs;
import static org.junit.jupiter.api.Assertions.*;import java.time.*;import org.junit.jupiter.api.Test;
class SourceContractFactsTest {
 static final Instant NOW=Instant.parse("2026-01-01T00:10:00.000000Z");
 private SourceContractFacts.Evidence value(String id,long version,String epoch,long total,long events,int nodes,Instant observed,Instant received,Instant read,Instant reviewed){return new SourceContractFacts.Evidence(id,version,epoch,total,events,nodes,observed,received,read,reviewed);}
 @Test void completeZeroAndPositiveExactFactsRemainRedacted(){var zero=value("fictional-source",1,"a".repeat(64),0,0,1,NOW,NOW,NOW,NOW);assertEquals(0,zero.totalFailures());assertEquals("SourceContractFacts[redacted]",zero.toString());var large=value("fictional-source",9007199254740991L,"b".repeat(64),9007199254740991L,25600,128,NOW,NOW,NOW,NOW);assertEquals(25600,large.eventsInWindow());assertEquals(128,large.nodeCount());}
 @Test void absentNodeCapacityAndUnsafeCountsNeverMeanHealthy(){for(int nodes:new int[]{0,129})assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,nodes,NOW,NOW,NOW,NOW));for(long total:new long[]{-1,9007199254740992L})assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),total,0,1,NOW,NOW,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),1,2,1,NOW,NOW,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),201,201,1,NOW,NOW,NOW,NOW));}
 @Test void identitiesMustBeNativeAndClosed(){for(String id:new String[]{"","fictional\nsource","测".repeat(81)})assertThrows(IllegalArgumentException.class,()->value(id,1,"a".repeat(64),0,0,1,NOW,NOW,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",0,"a".repeat(64),0,0,1,NOW,NOW,NOW,NOW));for(String epoch:new String[]{"fictional", "A".repeat(64)})assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,epoch,0,0,1,NOW,NOW,NOW,NOW));}
 @Test void allClockAndOriginalReviewFactsAreMandatory(){assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,null,NOW,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,NOW,null,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,NOW,NOW,null,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,NOW,NOW,NOW,null));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,NOW.plusNanos(1),NOW,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,NOW.plusSeconds(1),NOW,NOW,NOW));assertThrows(IllegalArgumentException.class,()->value("fictional-source",1,"a".repeat(64),0,0,1,NOW,NOW,NOW,NOW.plusSeconds(1)));}
}
